create table tb_category (created_at TIMESTAMP, id bigint generated by default as identity, updated_at TIMESTAMP, name varchar(255), primary key (id));
create table tb_perfil (id bigint generated by default as identity, name varchar(255), primary key (id));
create table tb_product (price float(53), created_at TIMESTAMP, id bigint generated by default as identity, updated_at TIMESTAMP, description varchar(255), img_url varchar(255), name varchar(255), primary key (id));
create table tb_product_category (id_category bigint not null, id_product bigint not null, primary key (id_category, id_product));
create table tb_user (created_at TIMESTAMP, id bigint generated by default as identity, updated_at TIMESTAMP, email varchar(255), name varchar(255), password varchar(255), phone varchar(255), primary key (id));
create table tb_user_perfil (id_perfil bigint not null, id_user bigint not null, primary key (id_perfil, id_user));
alter table if exists tb_product_category add constraint FKmbt47wj35n9he7pofy5mgyh75 foreign key (id_category) references tb_category;
alter table if exists tb_product_category add constraint FK6kdysltdkw0519op8r02iflt foreign key (id_product) references tb_product;
alter table if exists tb_user_perfil add constraint FKml01gsx6pqmda1s0ta9n146oa foreign key (id_perfil) references tb_perfil;
alter table if exists tb_user_perfil add constraint FKex75knqtcyb5rvboabi57dx2o foreign key (id_user) references tb_user;
